// Fan out: emit one n8n item per configured feed.
// Why: the HTTP node then runs once per source, so a single dead feed fails only its
// own item and drops into the error branch instead of killing the whole execution.
const config = $('Config').first().json;
const sources = Array.isArray(config.sources) ? config.sources : [];

if (sources.length === 0) {
  throw new Error('Config.sources is empty. Add at least one RSS source before running.');
}

return sources.map((source) => ({
  json: {
    sourceId: source.id,
    sourceName: source.name,
    sourceUrl: source.url,
    sourceWeight: Number(source.weight) || 1,
  },
}));

// Flatten wildly inconsistent RSS into one predictable article shape.
//
// Real-world problems this handles:
//   - <item> is an object when a feed has exactly one entry, an array otherwise
//   - titles/descriptions arrive CDATA-wrapped, HTML-escaped, or full of markup
//   - <link> is a string in RSS 2.0 but an array of objects in Atom
//   - dates come as RFC-822, ISO-8601, or dc:date
//   - the same story appears in two feeds with different tracking parameters
const config = $('Config').first().json;
const lookbackMs = (Number(config.lookbackHours) || 36) * 60 * 60 * 1000;
const cutoff = Date.now() - lookbackMs;

const asArray = (value) => (value == null ? [] : Array.isArray(value) ? value : [value]);

const text = (value) => {
  if (value == null) return '';
  // XML→JSON can hand back a string, { _: 'text' }, or { '#text': 'text' }.
  const raw = typeof value === 'object' ? (value._ ?? value['#text'] ?? '') : value;
  return String(raw)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
};

const linkOf = (item) => {
  if (typeof item.link === 'string') return item.link;
  const links = asArray(item.link);
  const withHref = links.find((link) => link?.$?.href);
  return withHref?.$?.href ?? text(links[0]) ?? '';
};

// Strip tracking params so the same article arriving from two feeds hashes identically.
const canonicalUrl = (url) => {
  try {
    const parsed = new URL(String(url));
    [...parsed.searchParams.keys()]
      .filter((key) => /^(utm_|fbclid|gclid|ref$|oc$)/i.test(key))
      .forEach((key) => parsed.searchParams.delete(key));
    parsed.hash = '';
    return parsed.toString();
  } catch {
    return String(url || '').trim();
  }
};

// djb2 — small, dependency-free, stable across runs. This is the idempotency key.
const hash = (value) => {
  let h = 5381;
  for (let i = 0; i < value.length; i += 1) h = ((h << 5) + h + value.charCodeAt(i)) | 0;
  return 'a' + (h >>> 0).toString(36);
};

const articles = [];

for (const entry of $input.all()) {
  const data = entry.json;
  const sourceName = data.sourceName || 'Unknown source';
  const sourceWeight = Number(data.sourceWeight) || 1;

  const channel = data?.rss?.channel ?? data?.channel ?? null;
  const rawItems = channel ? asArray(channel.item) : asArray(data?.feed?.entry);

  for (const item of rawItems) {
    const title = text(item.title);
    const url = canonicalUrl(linkOf(item));
    if (!title || !url) continue;

    const publishedRaw = item.pubDate ?? item.published ?? item.updated ?? item['dc:date'];
    const parsedDate = new Date(text(publishedRaw));
    const publishedMs = Number.isNaN(parsedDate.getTime()) ? Date.now() : parsedDate.getTime();

    // Time window keeps the digest about *today* and caps how much text reaches the LLM.
    if (publishedMs < cutoff) continue;

    articles.push({
      json: {
        hash: hash(url.toLowerCase()),
        title,
        url,
        summarySource: text(
          item.description ?? item.summary ?? item['content:encoded'] ?? '',
        ).slice(0, 600),
        publishedAt: new Date(publishedMs).toISOString(),
        sourceName,
        sourceWeight,
      },
    });
  }
}

return articles;

// Reached only through the HTTP node's error output (onError: continueErrorOutput).
// The run stays alive, and the failure travels downstream as data so the digest can
// honestly say "2 of 3 sources responded" instead of silently reporting less news.
return $input.all().map((item) => ({
  json: {
    __degradedSource: true,
    sourceName: item.json.sourceName || 'Unknown source',
    sourceUrl: item.json.sourceUrl || '',
    reason:
      item.json.error?.message ||
      item.json.error?.description ||
      item.json.message ||
      'Feed request failed after retries',
    failedAt: new Date().toISOString(),
  },
}));

// The decision layer: collapse duplicates, drop anything already sent, score what is
// left against the business keyword list, and keep only the top N.
const config = $('Config').first().json;
const minScore = Number(config.minScore) || 1;
const maxItems = Number(config.maxItems) || 8;
const keywords = Array.isArray(config.keywords) ? config.keywords : [];

const incoming = $input.all().map((item) => item.json);
const degraded = incoming.filter((row) => row.__degradedSource);
const candidates = incoming.filter((row) => !row.__degradedSource);

// --- Idempotency, two layers ------------------------------------------------------
// Layer 1: workflow static data. Fast and dependency-free, but n8n only persists it on
// production (scheduled) executions — never on manual ones.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seenHashes)) store.seenHashes = [];
const seen = new Set(store.seenHashes.map(String));

// Layer 2: the Google Sheet history. Survives manual runs and is human-auditable, which
// is what actually makes it safe for a reviewer to hit Execute twice in a row.
try {
  for (const row of $('Load Seen Hashes').all()) {
    if (row.json?.hash) seen.add(String(row.json.hash));
  }
} catch {
  // Sheet not configured yet — static data alone still prevents same-run duplicates.
}

const scoreOf = (article) => {
  const title = String(article.title || '').toLowerCase();
  const body = String(article.summarySource || '').toLowerCase();
  let score = 0;
  const matched = [];

  for (const keyword of keywords) {
    const term = String(keyword.term || '').toLowerCase();
    if (!term) continue;
    const weight = Number(keyword.weight) || 1;
    // A keyword in the headline is worth far more than one buried in the blurb.
    if (title.includes(term)) {
      score += weight * 3;
      matched.push(keyword.term);
    } else if (body.includes(term)) {
      score += weight;
      matched.push(keyword.term);
    }
  }

  return { score: score * (Number(article.sourceWeight) || 1), matched: [...new Set(matched)] };
};

const byHash = new Map();
let duplicatesCollapsed = 0;
let alreadySent = 0;
let belowThreshold = 0;

for (const article of candidates) {
  if (seen.has(article.hash)) {
    alreadySent += 1;
    continue;
  }
  if (byHash.has(article.hash)) {
    duplicatesCollapsed += 1;
    continue;
  }

  const { score, matched } = scoreOf(article);
  if (score < minScore) {
    belowThreshold += 1;
    continue;
  }

  byHash.set(article.hash, { ...article, score, matchedKeywords: matched });
}

const ranked = [...byHash.values()]
  .sort(
    (a, b) =>
      b.score - a.score || new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
  )
  .slice(0, maxItems);

return [
  {
    json: {
      hasNews: ranked.length > 0,
      articles: ranked,
      stats: {
        fetched: candidates.length,
        selected: ranked.length,
        duplicatesCollapsed,
        alreadySent,
        belowThreshold,
        sourcesOk: new Set(candidates.map((article) => article.sourceName)).size,
        sourcesFailed: degraded.map((row) => ({ sourceName: row.sourceName, reason: row.reason })),
        generatedAt: new Date().toISOString(),
      },
    },
  },
];

// Build the Gemini request body here rather than inline in the HTTP node, so the prompt
// is reviewable in git and the HTTP node stays a dumb transport.
const config = $('Config').first().json;
const { articles, stats } = $input.first().json;

// Only the fields the model needs. Sending less keeps us inside the free-tier token
// budget and stops the model from inventing detail it was never given.
const payload = articles.map((article) => ({
  id: article.hash,
  title: article.title,
  source: article.sourceName,
  blurb: String(article.summarySource || '').slice(0, 400),
}));

const instruction = [
  'You are a market analyst for Alba Cars, a used-car dealership and marketplace in Dubai, UAE.',
  'You will receive a JSON array of news articles.',
  '',
  'For EVERY article, return:',
  '  - id: copy the id exactly as given',
  '  - summary: one sentence, max 25 words, plain factual language, no hype',
  '  - category: exactly one of "Pricing", "Supply", "Regulation", "EV", "Industry", "Other"',
  '  - relevance: max 12 words on why a used-car dealer in the UAE should care',
  '',
  'Also return marketTakeaway: one sentence, max 30 words, summarising the day overall.',
  '',
  'Rules: use only facts present in the supplied text. If an article gives you too little',
  'to work with, say so plainly in the summary rather than guessing.',
  '',
  'Respond with JSON matching this shape exactly:',
  '{"marketTakeaway":"...","items":[{"id":"...","summary":"...","category":"...","relevance":"..."}]}',
  '',
  `Articles (${payload.length} total, ${stats.sourcesOk} sources):`,
  JSON.stringify(payload),
].join('\n');

return [
  {
    json: {
      geminiModel: config.geminiModel,
      geminiBody: {
        contents: [{ role: 'user', parts: [{ text: instruction }] }],
        generationConfig: {
          maxOutputTokens: 2048,
          // Forcing a JSON mime type is the difference between parsing a response and
          // regexing prose out of a markdown code fence.
          responseMimeType: 'application/json',
        },
      },
    },
  },
];

// Assemble the deliverable: subject line, HTML body, and the rows we will log.
//
// The LLM is an enhancement, never a dependency. If Gemini is rate-limited, errors, or
// returns something unparseable, this node falls back to an extractive summary taken
// from the feed text and the digest still goes out — just marked as unenriched.
const config = $('Config').first().json;
const ranked = $('Dedupe, Score & Rank').first().json;
const articles = ranked.articles || [];
const stats = ranked.stats || {};

let aiById = {};
let marketTakeaway = '';
let aiStatus = 'fallback';

try {
  const parts = $json?.candidates?.[0]?.content?.parts ?? [];
  const raw = parts
    .map((part) => part.text || '')
    .join('')
    .trim();
  const cleaned = raw
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/, '')
    .trim();
  const parsed = JSON.parse(cleaned);

  marketTakeaway = String(parsed.marketTakeaway || '').trim();
  for (const item of parsed.items || []) {
    if (!item?.id) continue;
    aiById[item.id] = {
      summary: String(item.summary || '').trim(),
      category: String(item.category || '').trim(),
      relevance: String(item.relevance || '').trim(),
    };
  }
  aiStatus = Object.keys(aiById).length > 0 ? 'ok' : 'empty';
} catch {
  aiStatus = 'fallback';
}

const firstSentence = (value) => {
  const sentence = String(value || '').split(/(?<=[.!?])\s/)[0] || '';
  return sentence.length > 220 ? `${sentence.slice(0, 217)}…` : sentence;
};

const escapeHtml = (value) =>
  String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const enriched = articles.map((article) => {
  const ai = aiById[article.hash];
  return {
    ...article,
    summary:
      ai?.summary || firstSentence(article.summarySource) || 'No summary text in the source feed.',
    category: ai?.category || 'Industry',
    relevance: ai?.relevance || '',
    aiEnriched: Boolean(ai),
  };
});

const categoryColour = {
  Pricing: '#b45309',
  Supply: '#0369a1',
  Regulation: '#7c3aed',
  EV: '#047857',
  Industry: '#475569',
  Other: '#475569',
};

const dateLabel = new Date().toLocaleDateString('en-AE', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'Asia/Dubai',
});

const cards = enriched
  .map((article) => {
    const colour = categoryColour[article.category] || '#475569';
    const published = new Date(article.publishedAt).toLocaleString('en-AE', {
      day: 'numeric',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: 'Asia/Dubai',
    });
    const relevanceLine = article.relevance
      ? `<div style="margin-top:10px;padding-left:10px;border-left:2px solid ${colour};color:#475569;font-size:13px;">
           <strong style="color:${colour};">Why it matters:</strong> ${escapeHtml(article.relevance)}
         </div>`
      : '';

    return `
      <div style="padding:18px 0;border-bottom:1px solid #e2e8f0;">
        <div style="font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:${colour};font-weight:700;">
          ${escapeHtml(article.category)}
          <span style="color:#94a3b8;font-weight:500;"> · ${escapeHtml(article.sourceName)} · ${published}</span>
        </div>
        <a href="${escapeHtml(article.url)}" style="display:block;margin-top:6px;font-size:17px;line-height:1.35;color:#0f172a;font-weight:600;text-decoration:none;">
          ${escapeHtml(article.title)}
        </a>
        <div style="margin-top:8px;font-size:14px;line-height:1.55;color:#334155;">
          ${escapeHtml(article.summary)}
        </div>
        ${relevanceLine}
        <div style="margin-top:10px;font-size:11px;color:#94a3b8;">
          relevance score ${article.score} · matched: ${escapeHtml((article.matchedKeywords || []).join(', ') || 'none')}
        </div>
      </div>`;
  })
  .join('');

const degradedBanner = (stats.sourcesFailed || []).length
  ? `<div style="margin:0 0 18px;padding:12px 14px;background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;font-size:13px;color:#92400e;">
       <strong>Partial run.</strong> ${stats.sourcesFailed.length} source(s) did not respond:
       ${escapeHtml(stats.sourcesFailed.map((source) => source.sourceName).join(', '))}.
       The digest below is built from the sources that did.
     </div>`
  : '';

const takeawayBlock = marketTakeaway
  ? `<div style="margin:0 0 20px;padding:16px 18px;background:#0f172a;border-radius:10px;color:#f8fafc;font-size:15px;line-height:1.5;">
       <div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#94a3b8;margin-bottom:6px;">Today's takeaway</div>
       ${escapeHtml(marketTakeaway)}
     </div>`
  : '';

const html = `<!doctype html>
<html><body style="margin:0;padding:24px 12px;background:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:640px;margin:0 auto;background:#ffffff;border-radius:14px;padding:28px 26px;box-shadow:0 1px 3px rgba(15,23,42,.08);">
    <div style="padding-bottom:18px;border-bottom:2px solid #0f172a;">
      <div style="font-size:21px;font-weight:700;color:#0f172a;letter-spacing:-.02em;">${escapeHtml(config.brandName || 'Alba Market Pulse')}</div>
      <div style="margin-top:4px;font-size:13px;color:#64748b;">UAE automotive market intelligence · ${dateLabel}</div>
    </div>
    <div style="padding-top:20px;">
      ${degradedBanner}
      ${takeawayBlock}
      ${cards}
    </div>
    <div style="margin-top:22px;padding-top:16px;border-top:1px solid #e2e8f0;font-size:11px;color:#94a3b8;line-height:1.7;">
      ${stats.fetched} articles scanned · ${stats.selected} selected · ${stats.duplicatesCollapsed} duplicates collapsed ·
      ${stats.alreadySent} already sent previously · ${stats.belowThreshold} below relevance threshold<br>
      summaries: ${aiStatus === 'ok' ? 'Gemini' : 'extractive fallback (LLM unavailable)'} ·
      generated by n8n at ${new Date(stats.generatedAt || Date.now()).toISOString()}
    </div>
  </div>
</body></html>`;

return [
  {
    json: {
      subject: `${config.brandName || 'Alba Market Pulse'} — ${enriched.length} stories · ${dateLabel}`,
      html,
      aiStatus,
      marketTakeaway,
      articles: enriched,
      stats,
    },
  },
];

// The digest is one item (one email). The history log needs one row per article, so
// fan back out here. Runs after the email is sent: nothing is recorded as "delivered"
// until it actually was.
const digest = $('Build Digest Email').first().json;

return (digest.articles || []).map((article) => ({
  json: {
    hash: article.hash,
    sentAt: new Date().toISOString(),
    title: article.title,
    url: article.url,
    source: article.sourceName,
    category: article.category,
    score: article.score,
    summary: article.summary,
    aiEnriched: article.aiEnriched ? 'yes' : 'no',
  },
}));

// Commit the idempotency ledger LAST, after the email is out and the history row is
// written. Ordering matters: if delivery fails, these hashes stay unseen and the next
// run retries them instead of silently swallowing a day of news.
const digest = $('Build Digest Email').first().json;
const store = $getWorkflowStaticData('global');

if (!Array.isArray(store.seenHashes)) store.seenHashes = [];

const fresh = (digest.articles || []).map((article) => article.hash);
const merged = [...store.seenHashes, ...fresh];

// Keep the ledger bounded — a rolling window is enough to stop repeats, and it stops
// static data growing without limit across months of daily runs.
store.seenHashes = [...new Set(merged)].slice(-500);
store.lastRunAt = new Date().toISOString();
store.lastRunCount = fresh.length;

return [
  {
    json: {
      committed: fresh.length,
      ledgerSize: store.seenHashes.length,
      lastRunAt: store.lastRunAt,
      note: 'Static data persists on production (scheduled) executions only — the Google Sheet layer covers manual runs.',
    },
  },
];
